# Reuse the side-on placement pose that successfully placed the first bottle.
for _ in range(3):
    result = p.move_ahead()
    brief(result)
    if not result.get("valid_action", True):
        break
brief(p.rotate("left"))
brief(p.look("up"))
held = p.query_inventory()
toilets = [o for o in p.detect_objects("Toilet") if o["objectType"] == "Toilet"]
if held and toilets:
    brief(p.put_object(held[0]["objectId"], toilets[0]["objectId"]))
print("verification", p.check_success())

# If the occupied tank prevents placement from this angle, try nearby side views.
if p.query_inventory():
    for direction in ("down", "up"):
        brief(p.look(direction))
        toilets = [o for o in p.detect_objects("Toilet") if o["objectType"] == "Toilet"]
        if toilets:
            brief(p.put_object(p.query_inventory()[0]["objectId"], toilets[0]["objectId"]))
        if not p.query_inventory():
            break
if p.query_inventory():
    brief(p.rotate("left"))
    brief(p.move_ahead())
    brief(p.rotate("right"))
    toilets = [o for o in p.detect_objects("Toilet") if o["objectType"] == "Toilet"]
    if toilets:
        brief(p.put_object(p.query_inventory()[0]["objectId"], toilets[0]["objectId"]))
print("final verification", p.check_success())

